function [h] = initial_momenta(nr, h0, h_target)
%INITIAL_MOMENTA  Every rotor's momentum [N m s] at the start: the scenario's h0 for each of the nr rotors, or, when it states none
%   (nan), the flight software's target for that rotor.
%   nr: int (passed a whole number)
%   h0: real[1] (passed a plain number)
%   h_target: real[1][DYN_NR] (passed a plain number)
%   returns h: real[1][DYN_NR] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    h = zeros(8, 1);
    h = zeros(8, 1);
    for i = (0):((nr) - 1)
        h((i) + 1) = asils.pc.choose_lazy(isnan(h0), @() h_target((i) + 1), @() h0);
    end
end
